/* определение пола по имени (казахские + русские) */
const FEMALE_NAMES = new Set([
  "мадина","айгерим","айгуль","аружан","камила","дана","алина","аяулым","дильназ",
  "жанель","инкар","карина","лаура","мерует","сабина","томирис","ажар","балжан",
  "гульнара","диана","замира","карлыгаш","назерке","сауле","фатима","аружан","аня",
  "мария","софия","анна","виктория","екатерина","дарья","полина","алиса","ева",
]);
function detectGender(name) {
  const n = (name || "").trim().toLowerCase();
  if (FEMALE_NAMES.has(n)) return "girl";
  // эвристика: женские обычно на -а/-я (но не казахские мужские типа Мұса)
  if (/[ая]$/.test(n) && !["мұса","муса","аллаберген"].includes(n)) return "girl";
  return "boy";
}
function ageGroup(age) {
  if (age <= 8) return "junior";
  if (age <= 11) return "middle";
  return "senior";
}

