const TWIN_CITIES = ["Астана","Алматы","Шымкент","Караганда"];

/* строит данные зеркального профиля под текущего ребёнка */
function buildTwin(childName, childAge) {
  const g = detectGender(childName);      // girl | boy
  const grp = ageGroup(childAge);         // junior | middle | senior
  const photo = TWIN_PHOTOS[`${grp}_${g}`];
  // выбор имени/города детерминированно, но «случайно» от возраста
  const names = TWIN_NAMES[grp][g];
  const name = names[childAge % names.length];
  const city = TWIN_CITIES[childAge % TWIN_CITIES.length];
  return {
    name, age: childAge, city, photo,
    match: 95,
    shared: ["Алгоритмическое мышление", "Толерантность к фрустрации", "Пространственное мышление"],
    achievements: TWIN_ACHIEVEMENTS[grp],
  };
}

