/* строит 5 карточек «схожие профили» с возрастами вразброс вокруг возраста ребёнка */
function buildCases(childAge, childName) {
  const grp = ageGroup(childAge);
  const pool = CASE_POOLS[grp];
  const bounds = { junior: [6, 8], middle: [9, 11], senior: [12, 15] }[grp];
  // возрасты вразброс: сам возраст + соседние, в пределах группы, без повторов подряд
  const spread = [0, 1, -1, 2, -2];
  const ages = spread.map((d) => {
    let a = childAge + d;
    if (a < bounds[0]) a = bounds[0] + (bounds[0] - a);
    if (a > bounds[1]) a = bounds[1] - (a - bounds[1]);
    return Math.max(bounds[0], Math.min(bounds[1], a));
  });
  const genders = ["boy", "girl", "boy", "girl", "boy"]; // чередование
  const childLower = (childName || "").trim().toLowerCase();
  return ages.map((age, i) => {
    const g = genders[i];
    const list = pool.names[g];
    let name = list[(childAge + i) % list.length];
    if (name.toLowerCase() === childLower) name = list[(childAge + i + 1) % list.length];
    const was = pool.was[(childAge + i) % pool.was.length];
    const [now, tag] = pool.now[(childAge + i * 2) % pool.now.length];
    const city = TWIN_CITIES[(childAge + i) % TWIN_CITIES.length];
    return { name: `${name}, ${age}`, city, was, now, tag };
  });
}


/* сегодняшняя дата в формате «4 августа 2026» */
function todayRu() {
  const months = [
    "января", "февраля", "марта", "апреля", "мая", "июня",
    "июля", "августа", "сентября", "октября", "ноября", "декабря",
  ];
  const d = new Date();
  return `${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
}

