/* Собирает объект ребёнка: реальные данные из сделки + демо-часть результатов. */
function buildChild(data) {
  const d = data || {};
  const name = String(d.childName || "").trim() || "ученик";
  const age = parseInt(d.childAge, 10) || 12;
  const deal = String(d.deal || "").replace(/\D/g, "");
  return {
    name, age,
    gender: detectGender(name),
    date: d.diagnosticDate || todayRu(),
    deal,
    docNo: `KD-2026-${(deal || "0").padStart(4, "0")}`,
    specialist: DEMO.specialist,
    specialistRole: DEMO.specialistRole,
    strengths: DEMO.strengths,
    notes: DEMO.notes,
    directions: DEMO.directions,
    discount: DEMO.discount,
  };
}

const API_GATE = "/api/zaklyuchenie";

/* номер сделки из ссылки (?deal=) — префилл поля входа, если специалист его добавил */
function prefillDeal() {
  try {
    const q = new URLSearchParams(window.location.search);
    return String(q.get("deal") || q.get("utm_term") || q.get("utm_content") || "").replace(/\D/g, "");
  } catch { return ""; }
}

export default function App() {
  // data — ответ гейта после входа: {deal, childName, childAge, diagnosticDate, expiry}
  const [data, setData] = useState(null);
  const [now, setNow] = useState(Date.now());

  // тик каждую секунду
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);

  const child = data ? buildChild(data) : null;
  const remaining = data && data.expiry ? Math.max(0, data.expiry * 1000 - now) : 0;
  const expired = !!(data && data.expiry) && remaining <= 0;

  return (
    <div style={{ minHeight: "100vh", background: C.paper, fontFamily: SANS, color: C.ink }}>
      <style>{`
        * { box-sizing: border-box; -webkit-font-smoothing: antialiased; }
        @keyframes rise { from { opacity:0; transform: translateY(14px);} to { opacity:1; transform:none; } }
        @keyframes fadein { from { opacity:0 } to { opacity:1 } }
        @keyframes barGrow { from { width: 0 } }
        @keyframes sealOpen { 0%{transform:scale(.9);opacity:0} 60%{transform:scale(1.03)} 100%{transform:scale(1);opacity:1} }
        .rise { animation: rise .6s cubic-bezier(.2,.7,.2,1) both; }
        .fadein { animation: fadein .8s ease both; }
        button { font-family: inherit; cursor: pointer; }
        button:focus-visible, input:focus-visible { outline: 2px solid ${C.amber}; outline-offset: 3px; }
        input { font-family: inherit; }
        @media (prefers-reduced-motion: reduce){ .rise,.fadein{animation:none} *{animation:none!important} }
        .recgrid { grid-template-columns: 1.15fr 1fr; }
        .statgrid { grid-template-columns: repeat(3,1fr); }
        .casegrid { grid-template-columns: 1fr 1fr; }
        .incgrid { grid-template-columns: 1fr 1fr; }
        @media (max-width:820px){
          .recgrid { grid-template-columns: 1fr !important; }
        }
        @media (max-width:620px){
          .statgrid, .casegrid, .incgrid { grid-template-columns: 1fr !important; }
        }
      `}</style>
      {!data
        ? <Gate onUnlock={setData} />
        : expired
          ? <Expired />
          : <Report child={child} remaining={remaining} />}
    </div>
  );
}

/* форматирование остатка в «Ч ч ММ мин» и «ЧЧ:ММ:СС» */
function fmtRemaining(ms) {
  const s = Math.floor(ms / 1000);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  return {
    short: `${h} ч ${String(m).padStart(2, "0")} мин`,
    clock: `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(sec).padStart(2, "0")}`,
    h, m, sec,
  };
}

