/* ─────────────────── ЭКРАН 0 — ВХОД ─────────────────── */
function Gate({ onUnlock }) {
  const [val, setVal] = useState(prefillDeal);
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const ERR = {
    bad_deal: "Введите номер сделки.",
    deal_not_found: "Сделка не найдена. Проверьте номер у специалиста.",
    amo_auth: "Не удалось обратиться к CRM. Сообщите специалисту.",
    server_not_configured: "Сервис не настроен. Сообщите специалисту.",
    _default: "Не удалось открыть заключение. Попробуйте ещё раз.",
  };

  const submit = async () => {
    const deal = String(val).replace(/\D/g, "");
    if (!deal) { setErr(ERR.bad_deal); return; }
    setLoading(true); setErr("");
    try {
      const r = await fetch(API_GATE, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ deal }),
      });
      const d = await r.json().catch(() => ({}));
      if (!(r.ok && d && d.ok)) { setErr(ERR[d && d.error] || ERR._default); setLoading(false); return; }
      onUnlock({
        deal,
        childName: d.childName || "",
        childAge: d.childAge || "",
        diagnosticDate: d.diagnosticDate || "",
        expiry: d.expiry || 0,
      });
    } catch (e) {
      setErr("Нет связи с сервером. Попробуйте ещё раз."); setLoading(false);
    }
  };

  return (
    <div style={{ minHeight: "100vh", background: C.navyDeep, display: "flex",
      alignItems: "center", justifyContent: "center", padding: 24, position: "relative", overflow: "hidden" }}>
      {/* атмосферная сетка на фоне */}
      <div aria-hidden style={{ position: "absolute", inset: 0, opacity: 0.05,
        backgroundImage: `linear-gradient(${C.white} 1px, transparent 1px), linear-gradient(90deg, ${C.white} 1px, transparent 1px)`,
        backgroundSize: "44px 44px" }} />
      <div className="rise" style={{ position: "relative", width: "100%", maxWidth: 440 }}>
        {/* логотип */}
        <div style={{ textAlign: "center", marginBottom: 40 }}>
          <div style={{ fontFamily: MONO, fontSize: 12, letterSpacing: ".28em",
            color: C.amber, fontWeight: 700 }}>KURSOR</div>
          <div style={{ fontFamily: MONO, fontSize: 9.5, letterSpacing: ".22em",
            color: "rgba(255,255,255,.4)", marginTop: 5 }}>ШКОЛА ПРОГРАММИРОВАНИЯ</div>
        </div>

        {/* печать/замок */}
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 26 }}>
          <div style={{ width: 66, height: 66, borderRadius: "50%",
            border: `1.5px solid ${C.amber}`, display: "flex", alignItems: "center",
            justifyContent: "center", position: "relative" }}>
            <div style={{ position: "absolute", inset: 6, borderRadius: "50%",
              border: `1px solid rgba(239,108,36,.35)` }} />
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
              <rect x="4" y="10.5" width="16" height="10.5" rx="2.5" fill={C.amber} />
              <path d="M7.5 10.5V7.2a4.5 4.5 0 019 0v3.3" stroke={C.amber} strokeWidth="1.8" fill="none" />
            </svg>
          </div>
        </div>

        <h1 style={{ fontFamily: SERIF, fontWeight: 700, fontSize: 27, lineHeight: 1.3,
          color: C.white, textAlign: "center", margin: "0 0 10px" }}>
          Персональное заключение
        </h1>
        <p style={{ fontSize: 14.5, lineHeight: 1.6, color: "rgba(255,255,255,.6)",
          textAlign: "center", margin: "0 0 32px" }}>
          Введите номер сделки — он открывает доступ<br />к заключению. Доступ действует 24 часа.
        </p>

        <label style={{ display: "block", fontFamily: MONO, fontSize: 10.5,
          letterSpacing: ".16em", color: "rgba(255,255,255,.45)", marginBottom: 9,
          textTransform: "uppercase" }}>Номер сделки</label>
        <input
          value={val}
          onChange={(e) => { setVal(e.target.value.replace(/\D/g, "")); setErr(""); }}
          onKeyDown={(e) => e.key === "Enter" && submit()}
          inputMode="numeric"
          placeholder="например, 51234"
          style={{
            width: "100%", background: "rgba(255,255,255,.06)",
            border: `1.5px solid ${err ? "#C4553E" : "rgba(255,255,255,.18)"}`,
            borderRadius: 10, padding: "16px 18px", fontSize: 22, letterSpacing: ".18em",
            color: C.white, textAlign: "center", fontFamily: MONO,
            transition: "border-color .2s",
          }}
        />
        {err && (
          <div style={{ fontSize: 13, color: "#E08C78", marginTop: 10, textAlign: "center" }}>
            {err}
          </div>
        )}

        <button onClick={submit} disabled={loading} style={{
          width: "100%", marginTop: 20, background: C.amber, color: C.white,
          border: "none", borderRadius: 10, padding: "16px", fontSize: 15.5,
          fontWeight: 700, letterSpacing: ".01em", opacity: loading ? 0.7 : 1,
        }}>{loading ? "Открываем…" : "Открыть заключение"}</button>

        <p style={{ fontSize: 12, color: "rgba(255,255,255,.4)", textAlign: "center",
          marginTop: 22, fontFamily: MONO, letterSpacing: ".04em" }}>
          Номер сделки выдал вам специалист.
        </p>
      </div>
    </div>
  );
}

/* ─────────────────── ОБЁРТКА ОТЧЁТА ─────────────────── */
function Report({ child, remaining }) {
  const [active, setActive] = useState(0);
  const refs = [useRef(), useRef(), useRef(), useRef()];
  const sections = ["Способности", "Рекомендация", "Основания", "Заключение"];

  useEffect(() => {
    if (typeof IntersectionObserver === "undefined") return;
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            const i = refs.findIndex((r) => r.current === e.target);
            if (i >= 0) setActive(i);
          }
        });
      },
      { rootMargin: "-45% 0px -50% 0px" }
    );
    refs.forEach((r) => r.current && obs.observe(r.current));
    return () => obs.disconnect();
  }, []);

  const go = (i) => refs[i].current?.scrollIntoView({ behavior: "smooth", block: "start" });

  return (
    <div className="fadein">
      {/* верхняя панель-документ */}
      <header style={{ position: "sticky", top: 0, zIndex: 20, background: C.navy,
        borderBottom: `1px solid rgba(255,255,255,.08)` }}>
        <div style={{ maxWidth: 940, margin: "0 auto", padding: "13px 22px",
          display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16 }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 12, minWidth: 0 }}>
            <span style={{ fontFamily: MONO, fontSize: 12, letterSpacing: ".22em",
              color: C.amber, fontWeight: 700, flexShrink: 0 }}>KURSOR</span>
            <span style={{ fontSize: 13, color: "rgba(255,255,255,.5)", whiteSpace: "nowrap",
              overflow: "hidden", textOverflow: "ellipsis" }}>
              Заключение · {child.name}, {child.age} {yearsWord(child.age)}
            </span>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 7, flexShrink: 0,
            fontFamily: MONO, fontSize: 11, color: "rgba(255,255,255,.4)" }}>
            <span style={{ width: 6, height: 6, borderRadius: 3, background: C.amber,
              boxShadow: `0 0 0 3px rgba(232,114,42,.2)` }} />
            осталось {fmtRemaining(remaining).short}
          </div>
        </div>
        {/* навигация по разделам */}
        <nav style={{ maxWidth: 940, margin: "0 auto", padding: "0 22px",
          display: "flex", gap: 4, overflowX: "auto" }}>
          {sections.map((s, i) => (
            <button key={s} onClick={() => go(i)} style={{
              background: "none", border: "none", padding: "11px 6px 12px",
              marginRight: 14, fontSize: 12.5, whiteSpace: "nowrap",
              color: active === i ? C.white : "rgba(255,255,255,.4)",
              borderBottom: `2px solid ${active === i ? C.amber : "transparent"}`,
              fontWeight: active === i ? 600 : 400, transition: "color .2s",
            }}>{s}</button>
          ))}
        </nav>
      </header>

      <main style={{ maxWidth: 940, margin: "0 auto", padding: "0 22px 80px" }}>
        <SecStrengths anchor={refs[0]} child={child} />
        <SecRecommend anchor={refs[1]} />
        <SecGrounds anchor={refs[2]} child={child} />
        <SecTerms anchor={refs[3]} remaining={remaining} child={child} />
      </main>

      <footer style={{ background: C.navyDeep, color: "rgba(255,255,255,.35)",
        fontFamily: MONO, fontSize: 11, textAlign: "center", padding: "22px",
        letterSpacing: ".04em" }}>
        Персональное заключение · доступ ограничен · KURSOR © 2026
      </footer>
    </div>
  );
}

