/* ─────────────────── 2 · РЕКОМЕНДАЦИЯ (почему год) ─────────────────── */
/* переиспользуемый линейный график */
function LineChart({ pts, unit, dimUpTo, direction, accentColor }) {
  const ACC = accentColor || C.amber;
  // direction: "down" (экранное время падает) или "up" (навык растёт)
  const W = 440, H = 240, PADL = 40, PADR = 34, PADT = 26, PADB = 36;
  const plotW = W - PADL - PADR, plotH = H - PADT - PADB;
  const X = (i) => PADL + (i / (pts.length - 1)) * plotW;
  const Y = (v) => PADT + (1 - v / 100) * plotH;
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", height: "auto", display: "block" }}
         preserveAspectRatio="xMidYMid meet">
      {[0, 25, 50, 75, 100].map((g) => (
        <g key={g}>
          <line x1={PADL} y1={Y(g)} x2={W - PADR} y2={Y(g)} stroke={C.line} strokeWidth="1" />
          <text x={PADL - 9} y={Y(g) + 3.2} textAnchor="end" fontSize="9" fill={C.mute} fontFamily={MONO}>{g}</text>
        </g>
      ))}
      {/* приглушённая зона 0–3 мес */}
      <rect x={X(0)} y={PADT} width={X(dimUpTo) - X(0)} height={plotH} fill={C.navy} opacity="0.04" />
      {/* базовая линия */}
      <polyline points={pts.map((p, i) => `${X(i)},${Y(p.v)}`).join(" ")}
        fill="none" stroke={C.navy} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" />
      {/* акцентный отрезок после точки перелома */}
      <polyline points={pts.slice(dimUpTo).map((p, i) => `${X(i + dimUpTo)},${Y(p.v)}`).join(" ")}
        fill="none" stroke={ACC} strokeWidth="3" strokeLinejoin="round" strokeLinecap="round" />
      {pts.map((p, i) => {
        const acc = i >= dimUpTo;
        const anchor = i === 0 ? "start" : i === pts.length - 1 ? "end" : "middle";
        return (
          <g key={i}>
            <circle cx={X(i)} cy={Y(p.v)} r="4" fill={acc ? ACC : C.navy}
              stroke={C.paperCard} strokeWidth="1.5" />
            <text x={X(i)} y={Y(p.v) - 12} textAnchor={anchor} fontSize="12" fontWeight="700"
              fill={acc ? ACC : C.navy} fontFamily={MONO}>{p.v}{unit}</text>
            <text x={X(i)} y={H - 12} textAnchor={anchor} fontSize="10.5" fill={C.mute} fontFamily={MONO}>{p.m}</text>
          </g>
        );
      })}
    </svg>
  );
}

