/* ─────────────────── склонение имени ─────────────────── */
function yearsWord(n) {
  const a = Math.abs(n) % 100, b = a % 10;
  if (a > 10 && a < 20) return "лет";
  if (b === 1) return "год";
  if (b >= 2 && b <= 4) return "года";
  return "лет";
}

function declineName(name) {
  const n = (name || "").trim();
  if (!n) return { nom: "", gen: "", dat: "" };
  const last = n.slice(-1).toLowerCase();
  // мужские на согласный: Даниил, Амир, Арман
  if (!"аяоеиуыэюь".includes(last)) {
    return { nom: n, gen: n + "а", dat: n + "у" };
  }
  if (last === "а") {
    const st = n.slice(0, -1);
    return { nom: n, gen: st + "ы", dat: st + "е" };
  }
  return { nom: n, gen: n, dat: n };
}
